create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,first_name text not null default '',last_name text not null default '',created_at timestamptz not null default now());
create table if not exists expense_categories(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,parent_id uuid references expense_categories(id) on delete set null,hidden boolean not null default false,created_at timestamptz not null default now());
create table if not exists expenses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,amount numeric(14,2) not null check(amount>=0),description text not null,date date not null,category_id uuid references expense_categories(id) on delete set null,deleted_at timestamptz,created_at timestamptz not null default now());
create table if not exists income(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,amount numeric(14,2) not null check(amount>=0),description text not null,date date not null,category text,created_at timestamptz not null default now());
create table if not exists assets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null,name text not null,amount numeric(14,2) not null default 0,deleted_at timestamptz,created_at timestamptz not null default now());
create table if not exists liabilities(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null,name text not null,amount numeric(14,2) not null default 0,deleted_at timestamptz,created_at timestamptz not null default now());
create table if not exists budgets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,category_id uuid references expense_categories(id) on delete cascade,month date not null,amount numeric(14,2) not null,created_at timestamptz not null default now());
create table if not exists goals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,target_amount numeric(14,2) not null,current_amount numeric(14,2) not null default 0,monthly_amount numeric(14,2) not null default 0,deleted_at timestamptz,created_at timestamptz not null default now());
create table if not exists tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,due_date date,priority text not null default 'normal',status text not null default 'open',note text,deleted_at timestamptz,created_at timestamptz not null default now());
create table if not exists notes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,content text not null default '',deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists user_preferences(id uuid primary key references auth.users(id) on delete cascade,theme text not null default 'light',text_size text not null default 'normal',assistant_enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null,title text not null,body text not null default '',read boolean not null default false,created_at timestamptz not null default now());
create table if not exists demo_portfolios(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null default 'תיק הדמה',cash numeric(14,2) not null default 100000,created_at timestamptz not null default now());
create table if not exists demo_holdings(id uuid primary key default gen_random_uuid(),portfolio_id uuid not null references demo_portfolios(id) on delete cascade,symbol text not null,name text not null,quantity numeric(18,6) not null default 0,avg_price numeric(18,6) not null default 0,created_at timestamptz not null default now());
create table if not exists demo_transactions(id uuid primary key default gen_random_uuid(),portfolio_id uuid not null references demo_portfolios(id) on delete cascade,symbol text not null,side text not null,quantity numeric(18,6) not null,price numeric(18,6) not null,created_at timestamptz not null default now());
create table if not exists imports(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,status text not null default 'processing',total_rows int not null default 0,processed_rows int not null default 0,created_at timestamptz not null default now());
create table if not exists import_rows(id uuid primary key default gen_random_uuid(),import_id uuid not null references imports(id) on delete cascade,raw_data jsonb not null default '{}'::jsonb,status text not null default 'review',confidence numeric(5,2),created_at timestamptz not null default now());
create table if not exists assistant_permissions(id uuid primary key references auth.users(id) on delete cascade,enabled boolean not null default false,updated_at timestamptz not null default now());
create table if not exists backups(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb);
create table if not exists restore_operations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,mode text not null,status text not null,created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['profiles','expense_categories','expenses','income','assets','liabilities','budgets','goals','tasks','notes','user_preferences','notifications','demo_portfolios','demo_holdings','demo_transactions','imports','import_rows','assistant_permissions','backups','restore_operations'] loop execute format('alter table %I enable row level security',t); end loop; end $$;
drop policy if exists profile_isolation on profiles;create policy profile_isolation on profiles for all using(id=auth.uid()) with check(id=auth.uid());
drop policy if exists categories_isolation on expense_categories;create policy categories_isolation on expense_categories for all using(user_id=auth.uid()) with check(user_id=auth.uid());
do $$ declare t text; begin foreach t in array array['expenses','income','assets','liabilities','budgets','goals','tasks','notes','notifications','imports','backups','restore_operations'] loop execute format('drop policy if exists %I on %I',t||'_isolation',t);execute format('create policy %I on %I for all using(user_id=auth.uid()) with check(user_id=auth.uid())',t||'_isolation',t); end loop; end $$;
create policy demo_portfolios_isolation on demo_portfolios for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy demo_holdings_isolation on demo_holdings for all using(exists(select 1 from demo_portfolios p where p.id=portfolio_id and p.user_id=auth.uid())) with check(exists(select 1 from demo_portfolios p where p.id=portfolio_id and p.user_id=auth.uid()));
create policy demo_transactions_isolation on demo_transactions for all using(exists(select 1 from demo_portfolios p where p.id=portfolio_id and p.user_id=auth.uid())) with check(exists(select 1 from demo_portfolios p where p.id=portfolio_id and p.user_id=auth.uid()));
create policy prefs_isolation on user_preferences for all using(id=auth.uid()) with check(id=auth.uid());
create policy assistant_isolation on assistant_permissions for all using(id=auth.uid()) with check(id=auth.uid());
create policy import_rows_isolation on import_rows for all using(exists(select 1 from imports i where i.id=import_id and i.user_id=auth.uid())) with check(exists(select 1 from imports i where i.id=import_id and i.user_id=auth.uid()));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,first_name,last_name) values(new.id,coalesce(new.raw_user_meta_data->>'first_name',''),coalesce(new.raw_user_meta_data->>'last_name','')) on conflict(id) do nothing;insert into public.user_preferences(id) values(new.id) on conflict(id) do nothing;insert into public.assistant_permissions(id) values(new.id) on conflict(id) do nothing;return new;end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();